#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
# shellcheck disable=SC2004
# apply-api-manager-policies.sh — Reconcile API Manager policies with the env-settings policy files.
#
# GENERATED by tests/parity/extract_inline_bash.py — do not hand-edit (change the Azure source or
# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/templates/tasks/apply-api-manager-policies.yml
#   step   : "Apply Policies to API Manager" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
# The shellcheck codes disabled above come from constructs inherited verbatim from that source.
#
# Inputs (environment):
#   MDF_API_ID                    <- ${{ parameters.apiId }}  [required]
#   MDF_BEARER_TOKEN              <- ${{ parameters.bearerToken }}  [required]
#   MDF_BG_ID                     <- ${{ parameters.bgId }}  [default: $(BG_ID)]
#   MDF_ENV_ID                    <- ${{ parameters.envId }}  [default: $(ENV_ID)]
#   MDF_POLICIES_PATH             <- ${{ parameters.policiesPath }}  [required]
#   MDF_UPDATE_TO_LATEST_VERSION  <- ${{ parameters.updateToLatestVersion }}  [default: false]

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_API_ID?MDF_API_ID is required (Azure parameter apiId)}"
: "${MDF_BEARER_TOKEN?MDF_BEARER_TOKEN is required (Azure parameter bearerToken)}"
: "${MDF_BG_ID=}"
: "${MDF_ENV_ID=}"
: "${MDF_POLICIES_PATH?MDF_POLICIES_PATH is required (Azure parameter policiesPath)}"
: "${MDF_UPDATE_TO_LATEST_VERSION=false}"

# >>> extracted body
BG_ID="${MDF_BG_ID}"
ENV_ID="${MDF_ENV_ID}"
API_ID="${MDF_API_ID}"
POLICIES_PATH="${MDF_POLICIES_PATH}"
UPDATE_TO_LATEST="${MDF_UPDATE_TO_LATEST_VERSION}"

echo "[DEBUG] ============================================"
echo "[DEBUG] APPLY API MANAGER POLICIES"
echo "[DEBUG] ============================================"
echo "[DEBUG] Parameters:"
echo "[DEBUG]   bgId=$BG_ID"
echo "[DEBUG]   envId=$ENV_ID"
echo "[DEBUG]   apiId=$API_ID"
echo "[DEBUG]   policiesPath=$POLICIES_PATH"
echo "[DEBUG]   updateToLatestVersion=$UPDATE_TO_LATEST"
echo "[DEBUG] ============================================"

if [ ! -d "$POLICIES_PATH" ]; then
  echo "[DEBUG] Policies folder NOT FOUND: $POLICIES_PATH"
  ci_log_warning "Policies folder not found: $POLICIES_PATH. Skipping."
  exit 0
fi

# Get available policy templates (for latest version lookup)
echo "[DEBUG] Fetching available policy templates from Exchange..."
TEMPLATES_BODY=$(curl -s --request GET \
  --url "https://anypoint.mulesoft.com/apimanager/xapi/v1/organizations/${BG_ID}/exchange-policy-templates?environmentId=${ENV_ID}&splitModel=true&latest=true&includeConfiguration=false" \
  --header "Authorization: Bearer ${MDF_BEARER_TOKEN}")
echo "[DEBUG] Policy templates count: $(echo "$TEMPLATES_BODY" | jq '. | length' 2>/dev/null || echo 'parse-error')"

# Get existing policies on the API instance
echo "[DEBUG] Fetching existing policies for API $API_ID..."
EXISTING_POLICIES=$(curl -s --request GET \
  --url "https://anypoint.mulesoft.com/apimanager/api/v1/organizations/${BG_ID}/environments/${ENV_ID}/apis/${API_ID}/policies?fullInfo=false" \
  --header "Authorization: Bearer ${MDF_BEARER_TOKEN}")
echo "[DEBUG] Existing policies count: $(echo "$EXISTING_POLICIES" | jq '. | length' 2>/dev/null || echo 'parse-error')"
echo "[DEBUG] Existing policies: $(echo "$EXISTING_POLICIES" | jq -r '.[].assetId' 2>/dev/null || echo 'none')"

# Find policy files
POLICY_FILES=$(find "$POLICIES_PATH" -maxdepth 1 -type f -name "*.json" | sort)

if [ -z "$POLICY_FILES" ]; then
  echo "[DEBUG] No *.json files found in $POLICIES_PATH"
  echo "No policy files found in $POLICIES_PATH. Skipping."
  exit 0
fi

echo "Found policy files: $(echo "$POLICY_FILES" | xargs -n 1 basename)"

# Track which asset IDs are defined in files (for cleanup)
FILE_ASSET_IDS=()

for POLICY_FILE in $POLICY_FILES; do
  CONTENT=$(cat "$POLICY_FILE")

  if ! echo "$CONTENT" | jq . &>/dev/null; then
    ci_log_warning "Invalid JSON in $POLICY_FILE. Skipping."
    continue
  fi

  POLICY_NAME=$(echo "$CONTENT" | jq -r '.policyName')
  PAYLOAD=$(echo "$CONTENT" | jq -c '.payload')
  ASSET_ID=$(echo "$PAYLOAD" | jq -r '.assetId')
  FILE_ASSET_IDS+=("$ASSET_ID")
  echo "[DEBUG] Processing policy file: $(basename "$POLICY_FILE") — name=$POLICY_NAME, assetId=$ASSET_ID"

  # Handle custom policies (set groupId to BG_ID)
  FILE_NAME=$(basename "$POLICY_FILE")
  if [[ "$FILE_NAME" == custom* ]]; then
    PAYLOAD=$(echo "$PAYLOAD" | jq --arg bgId "$BG_ID" '.groupId = $bgId')
  fi

  # Update to latest version if configured
  FINAL_PAYLOAD="$PAYLOAD"
  if [[ "$UPDATE_TO_LATEST" == "true" ]]; then
    latest_version=$(echo "$TEMPLATES_BODY" | jq -r --arg aid "$ASSET_ID" '.[] | select(.assetId == $aid) | .version')
    if [[ -n "$latest_version" && "$latest_version" != "null" ]]; then
      FINAL_PAYLOAD=$(echo "$PAYLOAD" | jq --arg v "$latest_version" '.assetVersion = $v')
    fi
  fi

  echo "Applying policy: $POLICY_NAME"

  # Create policy
  create_response=$(curl -i -s --location POST \
    "https://anypoint.mulesoft.com/apimanager/api/v1/organizations/${BG_ID}/environments/${ENV_ID}/apis/${API_ID}/policies" \
    --header "Content-Type: application/json" \
    --header "Authorization: Bearer ${MDF_BEARER_TOKEN}" \
    --data "$FINAL_PAYLOAD")

  HTTP_STATUS=$(echo "$create_response" | head -n 1 | awk '{print $2}')
  BODY=$(echo "$create_response" | sed -n '/^\r\{0,1\}$/,$p' | tail -n +2)

  if [[ "$HTTP_STATUS" == "201" ]]; then
    echo "  Policy '$POLICY_NAME' applied successfully."
    echo "[DEBUG]   Created: $POLICY_NAME (status=201)"

  elif [[ "$HTTP_STATUS" == "409" ]]; then
    # Policy exists — update it
    POLICY_ID=$(echo "$EXISTING_POLICIES" | jq -r --arg aid "$ASSET_ID" '.[] | select(.assetId == $aid) | .id')

    if [[ -n "$POLICY_ID" && "$POLICY_ID" != "null" ]]; then
      update_response=$(curl -i -s --request PATCH \
        --url "https://anypoint.mulesoft.com/apimanager/api/v1/organizations/${BG_ID}/environments/${ENV_ID}/apis/${API_ID}/policies/$POLICY_ID" \
        --header "Content-Type: application/json" \
        --header "Authorization: Bearer ${MDF_BEARER_TOKEN}" \
        --data "$FINAL_PAYLOAD")

      UPDATE_STATUS=$(echo "$update_response" | head -n 1 | awk '{print $2}')
      if [[ "$UPDATE_STATUS" == "200" ]]; then
        echo "  Policy '$POLICY_NAME' updated successfully."
      else
        ci_log_error "Failed to update policy '$POLICY_NAME'. Status: $UPDATE_STATUS"
        exit 1
      fi
    fi

  else
    ci_log_error "Failed to apply policy '$POLICY_NAME'. Status: $HTTP_STATUS"
    echo "Response: $BODY"
    exit 1
  fi
done

# Remove policies not defined in files
echo ""
echo "Checking for policies to remove..."
echo "[DEBUG] FILE_ASSET_IDS defined in config: ${FILE_ASSET_IDS[*]}"
CURRENT_COUNT=$(echo "$EXISTING_POLICIES" | jq '. | length')
echo "[DEBUG] Current policies on API instance: $CURRENT_COUNT"

for i in $(seq 0 $(($CURRENT_COUNT - 1))); do
  POLICY_ID=$(echo "$EXISTING_POLICIES" | jq -r ".[$i].id")
  POLICY_ASSET_ID=$(echo "$EXISTING_POLICIES" | jq -r ".[$i].assetId")

  FOUND=false
  for file_asset_id in "${FILE_ASSET_IDS[@]}"; do
    if [[ "$POLICY_ASSET_ID" == "$file_asset_id" ]]; then
      FOUND=true
      break
    fi
  done

  if [[ "$FOUND" == "false" ]]; then
    echo "  Removing policy not in files: $POLICY_ASSET_ID (ID: $POLICY_ID)"
    curl -s --request DELETE \
      --url "https://anypoint.mulesoft.com/apimanager/api/v1/organizations/${BG_ID}/environments/${ENV_ID}/apis/${API_ID}/policies/$POLICY_ID" \
      --header "Authorization: Bearer ${MDF_BEARER_TOKEN}" > /dev/null
  fi
done

echo "Policy management completed."
echo "[DEBUG] APPLY API MANAGER POLICIES COMPLETE"
